"use client";

import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { useUserStore } from "@/store/useUserStore";

export default function SplashPage() {
    const router = useRouter();
    const { isAuthenticated, mode, isProfileReady, isLanguageSelected } = useUserStore();
    const [done, setDone] = useState(false);

    useEffect(() => {
        const timer = setTimeout(() => {
            setDone(true);
            // Route decision
            if (isAuthenticated) {
                const langOk = isLanguageSelected ? isLanguageSelected() : false;
                if (!langOk) { router.push("/language-selection"); return; }
                const ready = isProfileReady ? isProfileReady() : false;
                if (mode === "worker") router.push(ready ? "/home" : "/setup/worker");
                else if (mode === "employer") router.push(ready ? "/dashboard" : "/setup/employer");
                else router.push("/role-selection");
            } else {
                const langOk = isLanguageSelected ? isLanguageSelected() : false;
                router.push(langOk ? "/role-selection" : "/language-selection");
            }
        }, 2500);
        return () => clearTimeout(timer);
        // eslint-disable-next-line react-hooks/exhaustive-deps
    }, [isAuthenticated, mode, router]);

    return (
        <div
            className="fixed inset-0 flex flex-col items-center justify-center overflow-hidden"
            style={{ background: "#0a2540" }}
        >
            {/* Logo */}
            <div className="flex flex-col items-center justify-center flex-1 gap-6">
                <div
                    className="w-24 h-24 rounded-full flex items-center justify-center"
                    style={{ background: "rgba(255,255,255,0.08)", border: "1.5px solid rgba(255,255,255,0.12)" }}
                >
                    <svg width="52" height="52" viewBox="0 0 52 52" fill="none">
                        <circle cx="20" cy="32" r="8" stroke="#e85d26" strokeWidth="3.5" fill="none" />
                        <circle cx="32" cy="20" r="8" stroke="#e85d26" strokeWidth="3.5" fill="none" />
                        <line x1="26" y1="26" x2="26" y2="26" stroke="#e85d26" strokeWidth="3.5" strokeLinecap="round" />
                        <path d="M26 26 C26 22 30 18 32 12" stroke="#e85d26" strokeWidth="3.5" strokeLinecap="round" fill="none" />
                        <path d="M26 26 C22 30 18 32 12 40" stroke="#e85d26" strokeWidth="3.5" strokeLinecap="round" fill="none" />
                        <circle cx="14" cy="38" r="3" fill="#e85d26" />
                        <circle cx="38" cy="14" r="3" fill="#e85d26" />
                    </svg>
                </div>

                <div className="text-center">
                    <h1 className="font-outfit font-bold text-white" style={{ fontSize: 32, lineHeight: 1.1 }}>
                        ShramSetu
                    </h1>
                    <p className="font-dmsans italic mt-2" style={{ fontSize: 16, color: "rgba(255,255,255,0.7)" }}>
                        काम मिलेगा। पैसा मिलेगा।
                    </p>
                </div>

                {/* Progress bar */}
                <div className="mt-4 rounded-full overflow-hidden" style={{ width: 192, height: 4, background: "rgba(255,255,255,0.15)" }}>
                    <div
                        className="h-full rounded-full"
                        style={{
                            background: "#e85d26",
                            animation: "splashProgress 2s linear forwards",
                        }}
                    />
                </div>
            </div>

            <p className="absolute bottom-8 font-dmsans" style={{ fontSize: 11, color: "rgba(255,255,255,0.35)", letterSpacing: "0.02em" }}>
                Powered by TrustBridge Verification
            </p>

            <style>{`
                @keyframes splashProgress {
                    from { width: 0% }
                    to { width: 100% }
                }
            `}</style>
        </div>
    );
}
